					R[i][j] = k;
				}

		H = new int [1 << (N-1)]; fill(H, -1);

		int res = solve(1, 1);
		assert res <= N;
		exit(res);
	}

	int [] H;

	int solve(int X, int J) {
		int B = (X & Q[J]);
		if (B == 0)
			return H[X] = INF;

		for (int i = 0; i < J; ++i) {
			int U = (1 << i), V = (1 << R[J][i]);
			if ((B&U) != 0 && (B&V) != 0)
				break;
			if (i == J-1)
				return H[X] = INF;
		}

		if (J == N-1)
			return H[X] = Integer.bitCount(X);

		int Y = (X | (1 << J)), res = INF;
		for (int j = 0; j < J; ++j) {
			int W = (1 << j);
			if ((Y & W) != 0) {
				int V = Y & (~W), R = H[V] == -1 ? solve(V, J+1) : H[V];
				res = min(res, R);
			}
		}
		int R = H[Y] == -1 ? solve(Y, J+1) : H[Y];
		res = min(res, R);
		return H[X] = res;		
	}

